INSERT INTO "products" ("id", "name", "brand", "type", "status", "price_cents", "compare_at_cents", "sku", "short", "description", "material", "care", "tags", "download", "position", "category_position", "featured", "allow_backorder", "cost_cents", "weight", "weight_unit", "package_length", "package_width", "package_height", "dimension_unit", "options", "seo_title", "seo_description", "rating_avg", "rating_count", "department_id", "category_id", "created_at", "updated_at") VALUES
  ('forma-overshirt', 'Forma Overshirt', 'VAREL', 'physical', 'published', 14800, NULL, 'VRL-FRM', 'Dry Italian cotton twill, boxy through the body.', 'Cut from a dry Italian cotton twill with a soft hand that breaks in over a few wears. Boxy through the body with a squared hem and a single patch pocket. Wear it open over a tee or buttoned as a shirt.', 'Cotton', 'Machine wash cold. Line dry.', ARRAY['new', 'essential']::varchar[], NULL, 0, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 4.67, 3, 1, 3, '2026-09-28T03:00:00.000Z'::timestamptz, now()),
  ('studio-wide-trouser', 'Studio Wide Trouser', 'VAREL', 'physical', 'published', 16800, NULL, 'VRL-STD', 'High rise, wide leg, pressed crease.', 'A high-rise trouser in a mid-weight wool blend, cut wide from the hip with a pressed crease that holds. Hidden hook closure and no belt loops, so the waist reads clean under knitwear.', 'Wool blend', 'Dry clean.', ARRAY['new']::varchar[], NULL, 1, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, NULL, 0, 1, 5, '2026-09-21T03:00:00.000Z'::timestamptz, now()),
  ('linea-knit-dress', 'Linea Knit Dress', 'VAREL', 'physical', 'published', 19800, 24000, 'VRL-LNA', 'Fine merino rib, ankle length.', 'Knitted in a fine merino rib that follows the body without gripping it. Ankle length with a boat neck and set-in sleeves. Wears alone in autumn and over a shirt through winter.', 'Merino wool', 'Hand wash cold. Dry flat.', ARRAY['sale', 'new']::varchar[], NULL, 2, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 4.50, 2, 1, 1, '2026-09-14T03:00:00.000Z'::timestamptz, now()),
  ('axis-leather-sneaker', 'Axis Leather Sneaker', 'VAREL', 'physical', 'published', 17500, NULL, 'VRL-AXS', 'Vegetable-tanned leather, cupsole.', 'A low sneaker in vegetable-tanned Italian leather on a slim cupsole. Unlined at the collar so it softens with wear. Resolable by any cobbler.', 'Leather', 'Wipe with a damp cloth. Condition seasonally.', ARRAY['essential']::varchar[], NULL, 3, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 3.50, 2, 3, 14, '2026-06-02T03:00:00.000Z'::timestamptz, now()),
  ('frame-shoulder-bag', 'Frame Shoulder Bag', 'VAREL', 'physical', 'published', 24000, NULL, 'VRL-FRA', 'Structured leather, magnetic close.', 'A structured shoulder bag in vegetable-tanned leather with a magnetic closure and one interior slip pocket. Sits under the arm on a fixed strap. Holds a phone, a wallet and a paperback.', 'Leather', 'Store in the dust bag. Condition twice a year.', ARRAY['essential']::varchar[], NULL, 4, 0, true, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 5.00, 2, 4, 18, '2026-05-19T03:00:00.000Z'::timestamptz, now()),
  ('core-heavy-tee', 'Core Heavy Tee', 'VAREL', 'physical', 'published', 6800, NULL, 'VRL-COR', '240gsm organic cotton, squared body.', 'A 240gsm organic cotton jersey knitted in Portugal, garment-washed so it holds shape after the first wash. Squared through the body with a ribbed neck that stays flat.', 'Organic cotton', 'Machine wash cold. Tumble dry low.', ARRAY['new', 'essential']::varchar[], NULL, 5, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 4.67, 3, 2, 9, '2026-09-07T03:00:00.000Z'::timestamptz, now()),
  ('atelier-wool-coat', 'Atelier Wool Coat', 'VAREL', 'physical', 'published', 39500, NULL, 'VRL-ATL', 'Double-faced Italian wool, unlined.', 'Double-faced Italian wool from our mill in Biella, unlined and hand-finished at the edges. Cut long through the body with a dropped shoulder, so it layers over knitwear without bulk.', 'Wool', 'Dry clean. Brush after wear.', ARRAY['essential']::varchar[], NULL, 6, 0, true, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, 4.67, 3, 1, 7, '2026-04-14T03:00:00.000Z'::timestamptz, now()),
  ('terra-rib-knit', 'Terra Rib Knit', 'VAREL', 'physical', 'published', 12800, 16000, 'VRL-TER', 'Lambswool half-gauge rib.', 'A half-gauge lambswool rib spun in Biella and knitted in Portugal. Generous through the body so a shirt sits underneath, with a high crew neck that holds its shape.', 'Lambswool', 'Hand wash cold. Dry flat.', ARRAY['sale', 'new']::varchar[], NULL, 7, 0, true, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, NULL, 0, 2, 10, '2026-08-31T03:00:00.000Z'::timestamptz, now()),
  ('arc-minimal-watch', 'Arc Minimal Watch', 'VAREL', 'physical', 'published', 22000, NULL, 'VRL-ARC', '34mm steel case, sapphire crystal.', 'A 34mm brushed steel case on a Swiss quartz movement, with a sapphire crystal and an unmarked dial. Interchangeable 18mm strap.', 'Steel', 'Water resistant to 50m.', ARRAY['essential']::varchar[], NULL, 8, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, NULL, 0, 5, 25, '2026-03-24T03:00:00.000Z'::timestamptz, now()),
  ('transit-weekender', 'Transit Weekender', 'VAREL', 'physical', 'published', 28500, NULL, 'VRL-TRN', 'Waxed canvas, leather base.', 'Waxed cotton canvas with a vegetable-tanned leather base and handles. Fits three days of clothing and slides under a seat. Interior shoe compartment.', 'Canvas', 'Spot clean. Re-wax annually.', '{}'::varchar[], NULL, 9, 0, true, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, NULL, 0, 4, 21, '2026-02-10T03:00:00.000Z'::timestamptz, now()),
  ('care-guide-download', 'The Care Guide', 'VAREL', 'digital', 'published', 0, NULL, 'VRL-CARE', 'A 48-page PDF on keeping natural fibres.', 'Forty-eight pages on washing, drying, storing and repairing wool, cotton, linen and leather. Written with our mills and a Copenhagen repair studio. Delivered as a PDF, no shipping.', 'Digital', NULL, ARRAY['digital']::varchar[], 'varel-care-guide.pdf', 10, 0, false, false, NULL, NULL, 'kg', NULL, NULL, NULL, 'cm', '[]'::jsonb, NULL, NULL, NULL, 0, 6, 29, '2026-01-20T03:00:00.000Z'::timestamptz, now())
