INSERT INTO "collections" ("id", "slug", "title", "description", "image", "published", "featured_on_home", "position", "seo_title", "seo_description", "created_at", "updated_at") VALUES
  (1, 'the-autumn-edit', 'The autumn edit', 'Wool, rib and heavier cloth for the turn of the season. A coat to build on, knitwear that layers over a shirt, and the pieces we reach for once the light drops.', '{"src":"https://images.unsplash.com/photo-1646270968752-c2cbdb8e7f73","credit":"Photo by Meg MacDonald on Unsplash","creditHref":"https://unsplash.com/@missmeg_mac"}'::jsonb, true, true, 0, NULL, 'The autumn edit from VAREL: wool outerwear, rib knits and trousers chosen for the colder months.', now(), now()),
  (2, 'travel-light', 'Travel light', 'One bag, a few pieces that work together, nothing that creases badly. Everything here packs flat and wears well on the other side.', '{"src":"https://images.unsplash.com/photo-1523205565295-f8e91625443b","credit":"Photo by Mark West on Unsplash","creditHref":"https://unsplash.com/@markwest_"}'::jsonb, true, true, 1, NULL, 'Travel light with VAREL: a weekender, easy shirting and the pieces that pack flat.', now(), now())
