INSERT INTO "reviews" ("id", "product_id", "user_id", "name", "email", "rating", "title", "body", "status", "verified_purchase", "reply", "created_at", "updated_at") VALUES
  (1, 'core-heavy-tee', NULL, 'Noah Jensen', 'noah.jensen@example.com', 5, 'Finally, a tee that lasts', 'Heavy cotton, a neck that does not stretch out, and a boxy fit that still looks tidy. I bought a second one.', 'approved', true, NULL, (now() - interval '5538788.128 seconds'), (now() + interval '1611.933 seconds')),
  (2, 'forma-overshirt', NULL, 'Hannah Schmidt', 'hannah.schmidt@example.com', 5, 'My most worn piece this year', 'Works as a shirt and as a light jacket. The cotton has softened after a few washes without losing its shape.', 'approved', true, NULL, (now() - interval '5020388.128 seconds'), (now() + interval '1611.903 seconds')),
  (3, 'axis-leather-sneaker', NULL, 'Lukas Weber', 'lukas.weber@example.com', 4, 'Comfortable from day one', 'Minimal break-in, supple leather and a clean sole. They run true to size for me.', 'approved', true, NULL, (now() - interval '4156388.128 seconds'), (now() + interval '1611.950 seconds')),
  (4, 'atelier-wool-coat', NULL, 'Ida Larsen', 'ida.larsen@example.com', 5, 'Worth the wait for autumn', 'The wool is dense without being heavy, and the shoulder sits exactly where it should. I sized down once and it is still roomy over a knit.', 'approved', true, 'Thank you, Ida. The coat is cut to layer, so sizing down is the right call for a closer fit.', (now() - interval '3551588.128 seconds'), (now() + interval '1611.883 seconds')),
  (5, 'frame-shoulder-bag', NULL, 'Matteo Rossi', 'matteo.rossi@example.com', 5, 'Structured and practical', 'Fits a small notebook, phone and keys with room to spare. The strap length is right both on the shoulder and across the body.', 'approved', true, NULL, (now() - interval '3205988.128 seconds'), (now() + interval '1611.961 seconds')),
  (6, 'forma-overshirt', NULL, 'Sofie Andersen', 'sofie.andersen@example.com', 4, 'Great weight', 'Substantial fabric and neat stitching. The sleeves are a little long on me, so I wear them turned back once.', 'approved', true, NULL, (now() - interval '2860388.128 seconds'), (now() + interval '1611.908 seconds')),
  (7, 'core-heavy-tee', NULL, 'James Carter', 'james.carter@example.com', 4, 'Solid basic', 'Great fabric. It shrank very slightly after the first hot wash, so follow the care label.', 'approved', true, NULL, (now() - interval '2601188.128 seconds'), (now() + interval '1611.938 seconds')),
  (8, 'atelier-wool-coat', NULL, 'Olivia Brown', 'olivia.brown@example.com', 5, 'Quietly perfect', 'Clean lines, no hardware, beautiful lining. It reads expensive in the best, most understated way.', 'approved', true, NULL, (now() - interval '2341988.128 seconds'), (now() + interval '1611.890 seconds')),
  (9, 'linea-knit-dress', NULL, 'Aiko Tanaka', 'aiko.tanaka@example.com', 5, 'Soft and flattering', 'The rib knit holds its shape through the day and does not cling. Dressed up with heels or down with sneakers, it simply works.', 'approved', true, NULL, (now() - interval '1909988.128 seconds'), (now() + interval '1611.921 seconds')),
  (10, 'axis-leather-sneaker', NULL, 'Jonas Falk', 'jonas.falk@example.com', 3, 'Handsome, a bit narrow', 'The leather is lovely and the profile is exactly what I wanted, but they are narrow across the toe. Consider half a size up if you have wide feet.', 'approved', false, 'Thank you for the note, Jonas. We have added a fit line to the size guide for wider feet.', (now() - interval '1650788.128 seconds'), (now() + interval '1611.955 seconds')),
  (11, 'core-heavy-tee', NULL, 'Freya Nilsson', 'freya.nilsson@example.com', 5, 'Boxy in the right way', 'I wear the men’s small and it is the relaxed fit I was after. Holds colour well after many washes.', 'approved', true, NULL, (now() - interval '1305188.128 seconds'), (now() + interval '1611.944 seconds')),
  (12, 'atelier-wool-coat', NULL, 'Clara Vos', 'clara.vos@example.com', 4, 'Beautiful, runs a touch long', 'Lovely coat. I am 163 cm and it falls just below the knee, which I like, but shorter readers may want to check the length guide.', 'approved', false, NULL, (now() - interval '1045988.128 seconds'), (now() + interval '1611.897 seconds')),
  (13, 'forma-overshirt', NULL, 'Elin Berg', 'elin.berg@example.com', 5, 'Exactly as pictured', 'The stone colour is warm and easy to wear with everything. Packaging was lovely too.', 'approved', false, NULL, (now() - interval '786788.128 seconds'), (now() + interval '1611.915 seconds')),
  (14, 'linea-knit-dress', NULL, 'Maja Lind', 'maja.lind@example.com', 4, 'Lovely, a little sheer in light colours', 'Beautiful drape and very comfortable. I would wear a slip with the lighter shade, the darker one is fully opaque.', 'approved', false, NULL, (now() - interval '527588.128 seconds'), (now() + interval '1611.926 seconds')),
  (15, 'frame-shoulder-bag', NULL, 'Laura Meyer', 'laura.meyer@example.com', 5, 'Better in person', 'The leather has a gentle grain and the edges are finished beautifully. It already looks better with wear.', 'approved', false, NULL, (now() - interval '354788.128 seconds'), (now() + interval '1611.967 seconds')),
  (16, 'studio-wide-trouser', NULL, 'Petra Novak', 'petra.novak@example.com', 4, 'Great drape', 'The wide leg moves beautifully. I had them taken up a little, which was easy with the clean hem.', 'pending', false, NULL, (now() - interval '181988.128 seconds'), (now() + interval '1611.972 seconds')),
  (17, 'terra-rib-knit', NULL, 'Erik Dahl', 'erik.dahl@example.com', 2, 'Itchy at the collar', 'Nice colour and good weight, but the collar was scratchy for me. I wear it over a tee now.', 'pending', false, NULL, (now() - interval '95588.128 seconds'), (now() + interval '1611.977 seconds'))
