INSERT INTO "translations" ("id", "entity", "entity_id", "field", "locale", "value", "source", "source_hash", "created_at", "updated_at") VALUES
  (801, 'product', 'studio-wide-trouser', 'description', 'da', 'Bukser med høj talje i en mellemvægtig uldblanding, skåret vide fra hoften med en pressefold, der holder. Skjult hægtelukning og ingen bæltestropper, så taljen ligger rent under strik.', 'auto', '7401f792747dafa1', now(), now()),
  (802, 'product', 'studio-wide-trouser', 'description', 'de', 'Eine Hose mit hohem Bund aus einer mittelschweren Wollmischung, ab der Hüfte weit geschnitten, mit einer Bügelfalte, die hält. Verdeckter Hakenverschluss und keine Gürtelschlaufen, damit die Taille unter Strick ruhig wirkt.', 'auto', '7401f792747dafa1', now(), now()),
  (803, 'product', 'studio-wide-trouser', 'description', 'es', 'Un pantalón de tiro alto en mezcla de lana de peso medio, ancho desde la cadera y con una raya marcada que se mantiene. Cierre de gancho oculto y sin trabillas, para que la cintura quede limpia bajo el punto.', 'auto', '7401f792747dafa1', now(), now()),
  (804, 'product', 'studio-wide-trouser', 'description', 'fr', 'Un pantalon taille haute dans un mélange de laine d''épaisseur moyenne, coupé large dès la hanche avec un pli marqué qui tient. Fermeture à crochet invisible et sans passants, pour une taille nette sous la maille.', 'auto', '7401f792747dafa1', now(), now()),
  (805, 'product', 'studio-wide-trouser', 'description', 'sv', 'En byxa med hög midja i en medeltung ullblandning, vid från höften med ett pressat veck som håller. Dold hakknäppning och inga hällor, så att midjan ser ren ut under stickat.', 'auto', '7401f792747dafa1', now(), now()),
  (806, 'product', 'studio-wide-trouser', 'material', 'da', 'Uldblanding', 'auto', '3463646424918b9f', now(), now()),
